"""Explain local unpoison, reports, context addresses and study scope."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1781': ('숙제를 끝낸 뒤 검사표에 완료 표시를 하는 것과 같아요. 완료 표시를 붙이는 일이 숙제 내용을 대신 써 주지는 않아요.', '지역 변수의 준비됨 표시와 실행 조건을 이해합니다.', '검사 꺼짐, runtime 안, 정상 처리 세 줄을 쓰고 실제 unpoison 호출에 도달하는 경우를 표시하세요.', ['지역 변수는 함수 안에서 사용하는 변수예요. __msan_unpoison_alloca는 그 메모리의 검사 정보를 준비됨으로 바꾸는 도우미예요. unpoison이라는 말은 미준비 표시를 없앤다는 뜻으로 생각하면 돼요.', '이 함수가 변수의 실제 내용을 0으로 채우는 것은 아니에요. 프로그램이 데이터를 쓰는 작업과 검사표가 그 상태를 따라가는 작업을 구별하세요. address는 처리할 메모리 주소이고 size는 바이트 수예요.', '첫 조건은 KMSAN이 꺼졌거나 kmsan_in_runtime이 참인지 확인해요. runtime은 도구 자신의 처리를 실행 중인 상태예요. 둘 중 하나라도 해당하면 바로 돌아가서 아래의 표시 변경을 생략해요.', '정상 경로에서는 enter_runtime으로 들어가 internal_unpoison을 호출한 뒤 leave_runtime으로 나와요. 정상 상태 0에서 시작했다면 0 → 1 → 0의 흐름으로 생각할 수 있어요. 도구 자신의 일을 구별하기 위한 진입·종료예요.', '내부 함수의 마지막 checked 인자는 true예요. 이는 필요한 검사 정보가 없는 범위에 대한 진단을 요청하는 선택이에요. true라고 실제 데이터의 모든 안전 조건을 증명한다는 뜻은 아니에요.', '앞의 어셈블리 출력 도우미는 checked false였고 in_runtime 검사도 생략했어요. 이 지역 변수 도우미는 true를 전달하고 runtime 안이면 돌아가요. 이름에 unpoison이 공통으로 있어도 실행 조건은 원문에서 각각 확인해야 해요.'], [('지역 변수 도우미와 어셈블리 출력 도우미의 checked 값은 어떻게 다른가요?', ['둘 다 항상 false예요', '지역 변수는 true, 어셈블리 출력은 false예요'], '정답은 두 번째예요. 실제 내부 호출의 마지막 인자를 비교하면 알 수 있어요. 같은 unpoison 작업이라도 검사 조건을 정하는 옵션이 달라요.'), ('이 지역 변수 도우미는 runtime 안에서도 표시 변경을 계속하나요?', ['아니요. 첫 조건에서 돌아가요', '네. 어셈블리 도우미와 언제나 같아요'], '정답은 첫 번째예요. if 조건에 kmsan_in_runtime이 있어요. 다른 도우미에서 생략한 조건이 여기에는 있다는 점을 구별하세요.')]), 'os1782': ('문제가 생긴 이유를 알려 줄 수 있어도 특정 상자 위치까지 함께 알려 주는 것은 아닐 수 있어요. 경고 함수가 어떤 정보를 넘기는지 하나씩 읽어 봐요.', '주소 범위 보고와 값 사용 경고의 인자를 구별합니다.', 'origin, address, size, reason 네 칸에 받은 번호, NULL, 0, REASON_ANY를 적어 보세요.', ['__msan_warning은 준비되지 않은 값이 잘못된 방식으로 사용됐음을 알리는 도우미예요. 인자로 받은 origin은 문제의 원인 기록을 찾아가는 번호예요. 실제 원인 기록 내용 전체를 이 인자 하나에 담는 것은 아니에요.', 'KMSAN이 꺼졌거나 도구 자신의 처리 중이면 바로 돌아가요. 그렇지 않으면 enter_runtime을 호출하고 kmsan_report로 보고를 요청해요. 보고 호출이 정상적으로 돌아오면 leave_runtime으로 나와요.', '보고 함수에 origin은 받은 값을 그대로 전달해요. 하지만 address에는 NULL, size에는 0을 넣어요. NULL은 여기서 특정 메모리 주소를 제공하지 않는다는 표시예요. 실제 데이터의 첫 주소를 자동으로 계산해 넣지 않아요.', '첫 번째와 마지막 위치를 나타내는 off_first와 off_last도 0이고 user_addr도 NULL이에요. 따라서 이 호출을 특정 버퍼의 몇 번째부터 몇 번째까지 읽었다는 범위 보고로 해석하면 안 돼요.', '마지막 reason은 REASON_ANY예요. 이유를 구분하는 상수 이름이에요. 언제나 사용자 공간으로 복사하다 생긴 문제라는 COPY_TO_USER 값을 넣는 코드가 아니에요.', '예를 들어 origin 77을 받으면 원인 번호 77과 위의 빈 주소·0 길이를 넘겨요. 77은 예시 번호일 뿐이에요. 인자를 확인했다고 실제 커널 경고 화면을 띄운 것은 아니며, 최종 출력의 추가 조건은 보고 함수 안에서도 살펴야 해요.'], [('이 경고가 보고 함수에 넘기는 address와 size는 무엇인가요?', ['항상 원본 버퍼 주소와 한 페이지 크기예요', 'NULL과 0이에요'], '정답은 두 번째예요. 이 호출은 특정 주소 범위 대신 origin으로 값 사용 문제를 알려요. NULL과 0을 원래 버퍼 위치·길이로 바꿔 해석하지 마세요.'), ('보고 함수에 전달하는 reason은 무엇인가요?', ['REASON_ANY예요', '항상 COPY_TO_USER예요'], '정답은 첫 번째예요. 마지막 인자에 REASON_ANY가 직접 적혀 있어요. 이 경고를 특정 사용자 복사 경로로 한정할 수 없어요.')]), 'os1783': ('보관함 안의 서류를 모두 복사하는 대신 보관함 위치를 알려 줄 수 있어요. 이 함수도 검사 상태가 있는 곳의 주소를 돌려줘요.', '문맥 상태의 주소 반환과 실제 인자 복사를 구별합니다.', '큰 상자 ctx 안에 작은 상자 cstate를 그리고, 반환 화살표가 작은 상자의 주소를 가리키게 하세요.', ['컴파일러가 검사 코드를 붙인 함수는 인자에 관한 검사 정보를 주고받아야 해요. __msan_get_context_state는 그 정보가 들어 있는 상태 공간의 주소를 얻는 도우미예요. 실제 함수 인자 값들을 전부 검사하거나 복사하는 함수는 아니에요.', '본문은 return &kmsan_get_context()->cstate 한 줄이에요. 먼저 kmsan_get_context가 지금 사용할 검사 문맥을 선택해요. 문맥은 현재 작업에 필요한 상태들을 모아 놓은 구조예요.', '->cstate는 선택한 문맥 안의 cstate라는 부분을 가리켜요. 앞의 &는 그 부분의 주소를 얻는 기호예요. 따라서 결과는 cstate의 복사본이 아니라 원래 cstate를 찾아갈 포인터예요.', '예를 들어 큰 서랍 안에 검사표 묶음이 있다면, 서랍 전체를 새로 만드는 대신 그 묶음이 놓인 위치를 알려 주는 것과 같아요. 이 함수에는 새 메모리를 할당하거나 검사 배열을 복사하는 코드가 없어요.', '이 getter 자체에는 KMSAN이 꺼지면 NULL을 반환하는 if문도 없어요. 활성 여부에 따라 일찍 돌아가는 다른 검사 함수와 정책이 같다고 생각하면 안 돼요. 한 줄 반환식 그대로 읽어 보세요.', '주소를 얻었다는 사실만으로 모든 인자가 검사됐다는 뜻은 아니에요. 또한 다른 실행 문맥에서도 언제나 동일한 주소가 나온다고 단정하면 안 돼요. 주소는 kmsan_get_context가 선택한 문맥의 cstate에 속해요.'], [('이 getter가 반환하는 것은 무엇인가요?', ['모든 실제 인자 값을 복사한 데이터 배열이에요', '선택된 검사 문맥 안 cstate의 주소예요'], '정답은 두 번째예요. 반환식의 &와 ->cstate를 함께 읽으세요. 원래 상태 공간의 주소를 얻는 것이며 실제 인자를 통째로 복사하지 않아요.'), ('이 함수 본문에 검사가 꺼지면 NULL을 반환하는 분기가 있나요?', ['아니요. 그런 분기 없이 cstate 주소를 반환해요', '네. 검사가 꺼지면 반드시 NULL로 바꿔요'], '정답은 첫 번째예요. 본문에는 한 줄 반환식만 있어요. 다른 함수의 enabled 조건을 이 함수에도 있다고 가정하면 안 돼요.')]), 'os1784': ('자동차 설명서를 읽는 일, 작은 모형을 움직이는 일, 실제 자동차를 운전하는 일은 달라요. 커널 학습과 실제 검사 커널 실행도 나누어 생각해요.', '학습 화면·함수 모델·실제 검사 커널의 실행 범위를 구별합니다.', '세 칸에 브라우저 수업, 선택 함수 모델, 실제 KMSAN 커널을 적고 각 칸에서 무엇을 실행하는지 적어 보세요.', ['KMSAN은 실행 중 준비되지 않은 값을 사용하는 실수를 찾는 검사 도구예요. dynamic detector의 dynamic은 실제 실행을 살피는 방식이라는 뜻이에요. 컴파일러가 추가한 검사 코드와 커널 안의 처리 코드가 함께 일해요.', '브라우저 학습실은 설명을 읽고 문제를 푸는 곳이에요. 학습실을 열기 위해 컴퓨터의 커널을 KMSAN 커널로 바꿀 필요는 없어요. 페이지의 코드를 읽는 것만으로 실제 커널 검사가 켜지는 것도 아니에요.', '선택한 함수를 모델에서 직접 부르는 실습은 작은 범위의 동작을 확인해요. 모델은 필요한 주변 동작을 단순하게 흉내 낸 환경이에요. 이 실습이 통과했다고 운영체제 전체가 검사된 것은 아니에요.', '실제 KMSAN 커널 실험은 검사 코드를 포함해 커널을 빌드하고 그 커널을 실행하는 별도 과정이에요. 빌드는 소스에서 실행할 프로그램을 만드는 일이에요. 현재 학습실의 실행 조건과 이 과정의 조건을 섞지 마세요.', '프로젝트에 고정된 Linux v6.12 문서는 Clang 14.0.6 이상과 CONFIG_KMSAN 활성화를 안내하고, 그 문서 시점의 runtime 지원을 x86_64로 설명해요. 이는 이 버전 문서의 내용이며 최신 지원표를 조사한 결과는 아니에요.', '같은 문서는 KMSAN이 메모리를 많이 쓰고 전체 시스템을 느리게 하므로 실제 서비스 운영용으로 의도하지 않았다고 설명해요. 추가 검사표를 보관하고 검사 코드를 실행하는 데 자원이 들기 때문이에요. 여기서는 실제 검사 커널을 부팅했다고 주장하지 않고, 각 학습 활동이 확인하는 범위를 구별해요.'], [('브라우저 학습실을 열려면 먼저 컴퓨터 커널을 KMSAN 커널로 교체해야 하나요?', ['네. 모든 학습자가 커널부터 교체해야 해요', '아니요. 학습 화면과 실제 검사 커널은 별도예요'], '정답은 두 번째예요. 설명과 문제를 보는 웹 학습실은 커널 실험과 다른 환경이에요. 실제 커널을 빌드하고 부팅해야 했다는 뜻으로 혼동하지 마세요.'), ('고정된 v6.12 문서는 KMSAN을 비용 없이 항상 켜 두는 운영용 도구라고 설명하나요?', ['아니요. 메모리·실행 비용 때문에 운영용으로 의도하지 않았다고 해요', '네. 자원을 전혀 더 쓰지 않는다고 해요'], '정답은 첫 번째예요. 검사 정보 보관과 추가 실행에 비용이 들어요. 이 설명은 프로젝트가 고정한 버전의 공식 문서를 기준으로 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_441.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
